        self.left = left
        self.right = right

def inorder_traversal(root: TreeNode) -> list:
    if not root:  # Base case: empty leaf
        return []
    # Left Subtree + Root + Right Subtree
    return inorder_traversal(root.left) + [root.val] + inorder_traversal(root.right)

